import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"井","description":"高岛易断 - 井","frontmatter":{"title":"井","description":"高岛易断 - 井"},"headers":[],"relativePath":"zh/classics/takashima/048.md","filePath":"zh/classics/takashima/048.md"}'),i={name:"zh/classics/takashima/048.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="井" tabindex="-1">井 <a class="header-anchor" href="#井" aria-label="Permalink to “井”">​</a></h1><h2 id="井-1" tabindex="-1">井 <a class="header-anchor" href="#井-1" aria-label="Permalink to “井”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>井：改邑不改井，无丧无得，往来井井。汔至，亦未繘井，赢其瓶，凶。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>“井”，通也，物所通用也。古者建设都邑，必凿井以养民，即或邑有改迁，而井之制不改。人得井以为养，而井不因之见损，故“无丧”；井所以养人，而井不以此见功，故“无得”。但见往者往，来者来，人之就养于井者，亦未尝归功于井也。“繘”，所以引而下，“瓶”，所以盛而上，至若繘未下，而瓶已羸，则井为虚设，而繘亦为虚悬矣，故曰“凶”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>木上有水，井。君子以劳民劝相。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《坎》为水，在上，《巽》为木，在下，其象为“木上有水”，即《彖传》所谓“巽乎水而上水”之象也。君子玩其象，而修其德，以之“劳民劝相”。“劳”，用民力也，“劝”，劝道也，“相”，辅相也。《坎》为劳卦，互卦《兑》，《兑》为悦，悦以劳民；《兑》又为口，《巽》为同，为交，有同心协助之象，故曰“相”。天下之民无穷，一人之养难周，君子于是劳来之，劝相之，使比间族党相亲，贫穷患难相恤，开导诱掖，以尽其相生相养之道，如是则所以养民者，周恤完全，而无一人之漏养者，所谓“井养而不穷”也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：目下交木水相生之运，正可相助成事。</p><p>○　问战征：有水灭木之象，水军有厄，宜劳力相助，可以出险。</p><p>○　问功名：“木上有水”，有得春雨发生之象，功名可望。</p><p>○　问营商：有利过于本之象，吉。</p><p>○　问家宅：此屋栋柱，恐有水湿溃烂之患，宜急修葺。</p><p>○　一问婚姻：《坎》男《巽》女；男上于女，阴阳之正也，吉。</p><p>○　问疾病：肾水暴溢，宜急调治。</p><p>○　问六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>“旧井”者，坏而不治之井也；“禽”者，辘轳之轴，运繘者也，轴上刻以禽形，故曰“禽”。或谓轴转之音，似禽鸣也。初居最下，象井底，水涸泥污，故曰“井泥不食”，成为废井，井久有毒，故人不食。其井既废，则辘轳之禽，亦腐朽而无有矣，故曰“旧井无禽”。《象传》以“下也”释“井泥”，谓泥在井下，故不可食，以“时舍”释“旧井”，谓井已废旧，故为时所舍。按：《鲁语》“取名鱼，登川禽”，韦昭注：川禽，鳌蜃之属。《易林》《遁》之《井》曰：“老河空虚，旧井无鱼。”此无禽即蜃蛤鱼蛙之类，说亦有据。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：为时过运衰，不为世用。</p><p>○　问战征：有兵器朽旧，不克制胜之患。</p><p>○　问营商：货物陈腐，不可贩售。</p><p>○　问功名：年老无用。</p><p>○　问疾病：是旧症也。不治。</p><p>○　问婚姻：人品卑下，虽属旧亲，不成。</p><p>○　问讼事：必不得直。</p><p>○　问六甲：生男，防难育。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某来，请占气运，筮得《井》之《需》。</p><p>断曰：井既旧，有泥无禽，是废井也；在人则运退时衰，必见弃而无用也。占者得此。知其人品行卑下，为人所弃，难望进用之日也。卦爻初与四应，初之旧井，得四修之，即可无咎。今足下犹旧井也，甘辱泥涂，不自悔改，故终为世弃，不可复用也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>“井谷”者，泉穴也。《汉书·沟洫志》，“井下相通行水为井渠”，井固有旁穿孔穴，二动体《艮》，《艮》为穴也。“鲋”，鱼之小者，《子夏传》谓虾蟆。《井》五月之卦，故有虾蟆；《尔雅翼》，“鲋，鰿也”，今作鲫。二体《巽》，《巽》为风，风主虫，虾蟆与鱼，要皆不离夫介鳞虫类。“射鲋”者，古有射鱼，《淮南子·时则训》，“季冬之月，命渔师始渔，天子亲往射鱼”；《史记》：“秦始皇至芝罘射，得巨鱼。”井谷无巨鱼，所射者鲋耳。“瓮”，盛水之器，与瓶相类，二至四互《兑》，象《兑》口，《巽》在下，象底穿，故曰“瓮敝漏”，即《彖》所谓“羸其瓶”也。盖《井》之为水，以上汲为功，而谷水下注，如敝瓮之无底者，复何与于井养之功哉！而徒以射鲋为能，故君子所不取也。</p><h2 id="九二占" tabindex="-1">九二占 <a class="header-anchor" href="#九二占" aria-label="Permalink to “九二占”">​</a></h2><p>○　问时运：所得者小，所失者大矣。</p><p>○　问战征：误中敌计，军入幽谷，致破釜缺养而不得出。</p><p>○　问功名：弋获虚名，其何能久？</p><p>○　问营商：为贪意外之财，致失本分之利。</p><p>○　问婚姻：门地卑微，声名残败，不佳。</p><p>○　问家宅：此宅有废井，井口残破，水不可食。</p><p>○　问疾病：是下漏之症，医治可愈。</p><p>○　问失物：物已敝败，得亦无用。</p><p>○　问六甲：生男，防此儿有残疾。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>友人某来，请占气运，筮得《井》之《蹇》。</p><p>断曰：井曰“井养”，然井不能自养，亦在人取之以为养也；乃不取水而取鲋，取非所取，是失《井》之义也。今足下占气运，得《井》二爻，知足下素好学问，亦如井之有源；病在专尚旁门，不务正学，犹是谷水为井之旁穴，射鲋非井之应得，究何与于井养之义也？“瓮敝漏”者，为言井水下注，如人之流品日下也。爻象实为足下示警，足下当求通晓世情，躬行实践，毋徒盗虚誉也。</p><p>明治三十年，占司法省气运，筮得《井》之《蹇》。</p><p>断曰：此卦下三爻为井中之水，上三爻为汲水以供用也，故下三爻不吉，上三爻皆吉。我国近来许外国人杂居，一仿欧美各邦规则，定为法律，在我国人居住欧美各邦者，亦受欧美之保护，故我国亦保护彼国旅人，如出一辙也。今占得二爻，其立法恐有徒贪小利，转致失其大体，谓之“井谷射鲋，瓮敝漏”。司外务之任者，所宜注意焉。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“渫”，治也，谓治井而不停污也。初则“泥”，二则“漏”，三居《巽》之终，《巽》有洁齐之义，故为“井渫”。渫则泥去，漏塞，清洁可食。其有不食者，非井之咎也，犹人澡身浴德，惠泽足以养人，当局者莫之知，旁观者知之矣。“我”，则旁观自谓也，谓如此清泉，而竟弃之如遗，我则为之心侧矣。井既浚治，则可汲而用者，莫如此井也，此而不用，不明甚矣，安得明王出而用之也？是众人祈祷而求其用者也。“王”指五，三至五互《离》，故为明王。阳为福，喻王者登用贤才，则德泽单敷，遐迩受福，贤者之福，即明君之福，亦天下之福也。“并受其福”，是一井之利，遍及万家也。（附言）《井》为《震》宫五世之卦，凡问疾厄，得下卦多不治。下卦变则瓶体破，不能汲水，即《彖》辞所谓“羸其瓶，凶”。补治其破，犹病者得医而治也，凶尚可救。其象如此，余二十年来，屡占屡验，无一或爽。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：怀才不用，命为之也。</p><p>○　问战征：兵器既修，士卒可用，惜无主将，以致士气颓丧，为可惜也。</p><p>○　问营商：明见货物辐辏，可以获利，不知贩运，徒诿无用耳。</p><p>○　问功名：有才无命，为世所弃；两年后至五爻，可望登用。</p><p>○　问婚姻：目下不成，至五爻必得成就，须在二年后也。</p><p>○　问家宅：此宅必有旧井久湮，宜渫治之。得食此水，一家获福，若不渫不食，大为可惜。</p><p>○　问疾病：必是心神不安之症，宜饮症泉可愈。</p><p>○　问六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治二十六年一月，祝贺新年，偶谒某贵显，贵显顾余曰：近来有奇妙之《易》断乎？余曰：《易》象精微，诚心感格，无不奇妙。昨年十月间，与杉浦重刚诸君，会于星冈茶寮，为占众议院议会结局，得《井》三爻。当时政府与众议院，意见不合，势甚决裂，后上乞天裁，始得平允。是所谓井井有条者也。</p><p>断曰：《井》，一也，而食者众，所谓“往来井井”，有众之象焉。想井之始凿，赖众而成，迨井既成，则众皆得井而养，喻言议之建，赖众而倡，迨议既定，则众皆依议而行也。故在众议院，主张人民生活尚多不足，为之节省官费，整理财政，意在开国家富足之源也。在政府，谓议员不谙政体，不通时事，以致两议不协，譬如汲水者，来至井上，互论井水之清浊，而两下停汲，终归无用，究何济乎？局外者未免为之心忧矣，即所谓“井渫不食，为我心侧”者是也。政府既不允议院，议院欲力逼政府，彼此各执一见，遂至冲突，此势之不能中止也，于是惟有仰求宸断，即爻辞所谓“可用汲，王明，并受其福”是也。幸圣上至仁至明，能两酌其平，政府有可让者让之，议院有可容者容之，于适宜之中，立预算之准，以使上下各得其情，斯天下“并受其福”矣。贵显闻之，谓余能臆测时事，特假《易》以立说也。余曰：此乃《易》理之先机，能贯彻于事前，余不过就《易》论《易》，而其时事之应验，自不能出于《易》之外也。</p><p>明治二十三年七月，新泻审判所长富田祯次郎氏来访。氏，余旧知也，不相见数年矣，得见之余，互谈契阔，氏曰：我今来访，专为道谢往年《易》断也。乃详述从前求卜，得《井》之三爻。</p><p>辞曰：“井渫不食，为我心恻。可用汲，王明，并受其福。”是井水本清洁，无人汲之，井养之功无所施，喻人虽有才德，无人用之，则展布之能无所见，必得明王之赏识，拔而用之，斯不特一人受福，天下“并受其福”也。就爻位而推之，以五爻为任用之日，六爻当大任之时，盖即在三年四年间也，谓当必有应验也。至今日，断词一一灵验，不爽毫厘，心窃喜之，特来致谢。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>“甃”者，以砖垒井，防井之败坏者也。此卦三阳为泉，三阴为井，初六最下，曰“泥”，上六最上，曰“收”，四居其间，不失其正，故曰“甃”。凡井之坏，坏于污浊不修，而井遂至于无用，四能甃之，故得“无咎”。有四之甃乃得有五之“寒泉”，是助五以养人，皆赖四之甃也。甃井之功，不可为不大矣。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：正当运途改变之时，宜自修饬，不特无咎，可望上进。</p><p>○　问营商：宜整理旧业，自可获利。</p><p>○　问功名：修身立名，二三年后，可大得志。</p><p>○　问战征：诗云“修我矛戟，与子偕作”，在此时也。</p><p>○　问婚姻：尚须待时。</p><p>○　问家宅：此宅宜改修为吉。</p><p>○　问六甲：有弄瓦之象，生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>横滨港町接近居留地，有鱼鸟菜兽市场，此市场，依各国开港条约所设，其业最为繁盛。一日有友来，曰：近来横滨市场上，商人大起争论，遂至休业，有人欲出而调停，未得处理之方，特请一占。筮得《井》之《大过》。</p><p>断曰：就市中商业而论，彼此俱有关系，譬如汲井之用繘瓶也。有井而无繘瓶，则井水将何从而汲？有繘瓶而无井，则繘瓶亦终归无用。同在此市场贸易，知益则俱益，害则俱害，两相斗必致两败也。今占得三爻，曰“井甃，无咎”，“甃”者，治也，因井之败坏而重修之也。今两家商业，因此一争，未免败坏，出而修之者，是在四也。盖四即为居中调停之人，得四调停，而后五之“寒泉”，可以复食。四与五相隔一爻，一爻当一月，则来月必可和解，重复旧业矣。</p><p>占清法二国争据安南事由。本年三四月启衅，至今未得和战的讯，诸新闻纸所揭，皆由街谈巷说，未足信凭，余因先筮清国，得《井》之《大过》。</p><p>断曰：卦德为井养不穷，谓其井之大，而得其养者众矣。以喻清国之大，物产丰饶，他邦皆愿与贸易，受其润泽。故已汲者去，未汲者来，其贸易之品物无尽，犹井水取之不竭也。但清国航海之术未精，不能由己自输其物产，譬如井水不能自出，必待人汲之，而后能泽物。故今为安南事件，虽欲与法开战，而终归不战者，亦如井水之不能自动，可知清国必不起战也。万一清国决计开战，则于各国贸易，大有障碍，凡局外中立之国，必为之出而调停，曲意保护，犹是以砖垒井，不使污浊之得入也。“井甃，无咎”，此之谓也。自《井》四至《革》四爻，为七年，今后七年，清国必有改革之变。谚曰“唇亡齿寒”，我国亦宜严整预备也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>“冽”，水清也，井水在上，故冽。五为《坎》之主，位居中正，《坎》为寒泉，辰在子，子水也，属北方，故寒。按水之性，冬则温，夏则寒，是阴中纳阳，阳中纳阴，其性然也；《井》为五月之卦，是以冽而且寒。孟子曰，“夏日饮水，冬日饮汤”，当此仲夏，汲此寒泉而食之，为得其时焉。盖《井》自三“渫”之，四“甃”之，则“泥”去“漏”塞，而五之“寒泉”乃出，复之者众，斯受福者亦众矣。王者德润生民，遍及万方，亦如是耳。《井》旁通为《噬嗑》，“《噬嗑》，食也”，故曰“井冽，寒泉食”。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：家道必寒，幸运得其时，可望进用。</p><p>○　问营商：井出寒泉，喻言财源之长也，可望获利。</p><p>○　问功名：品行中正，可享鼎养之荣。</p><p>○　问家宅：有廉泉让水之风。</p><p>○　问婚姻：家风清白，同甘共苦，夫妇之正也。</p><p>○　问疾病：是外寒内热之症，宜服寒凉之剂。</p><p>○　问六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十二年，占山县伯气运，筮得《井》之《升》。</p><p>断曰：井者所以养人，然不汲之，则井泉虽冽，亦无所用其养，喻贤者泽足惠民，然不举之，则贤才在下，亦无以施其惠。今占山县伯气运，得《井》之五爻，知伯才德渊深，志操清洁，寒素起家，超升显要，其惠泽之敷，一如“王明”“用汲”，“并受其福”于无穷也。爻曰：“井甃”，喻言伯之气体清明也；曰“寒泉食”，喻言下民食伯之德者，恍若一酌寒泉，顿觉胞膈凉爽也。伯之恩惠无穷，伯之荣显，亦未有艾也。此年山县伯果任内阁总理。此占辞，当时上申三条公与伊藤伯。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“收”，谓辘轳收缩。“幕”井盖也，“勿幕”者，即《彖》所云“往来井井”，汲者众多，无昼无夜，取之不竭：在井固不擅其有，不私其利，任人汲灌，故“勿幕”也。上居《坎》之极，偶画两开，有“勿幕”之象。“孚”，指五，五为“王明”，能用汲者也。“元吉”，元，大也，谓井之利大，故吉亦大。“在上”者，谓上在井口，养人之功，从此而出。“大成”者，谓井养之道，至此而大成矣，凡爻辞阴柔在上，多不吉，在上“元吉”，惟《井》一卦而已。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：功德在世，信用在人，“大成，“元吉”，运之极盛者也。</p><p>○　问功名：有大用大受之象，非一官一邑之微也。</p><p>○　问营商：商务会集，利益浩繁，可久可大，无往不吉。</p><p>○　问婚姻：上应在三，三曰“并受其福”，知两姓皆吉。</p><p>○　问战征：凡军将发则撤幕，“勿幕”，即撤幕前进也。一战功成，故曰“大成”。吉。</p><p>○　问疾病：幕亦作暮，言旦夕可即愈也，吉。</p><p>○　问六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治三十年，占贸易景况，筮得《井》之《巽》。</p><p>断曰：此卦下《巽》木，上坎水，即《彖》所云“巽乎水而上水”，是为汲引井水之象。至上爻，则井之功用已成，“勿幕”者，王弼所谓“不擅其有，不私其利”也。今外商与我商从事贸易，我国不自输出，待外商舶运而往，犹井水之待人而汲。内三爻井水不食，为货物不能旺销，外三爻则泉美可食，汲取者众。四爻当七八月，五爻当九十月，上爻已在井口，当十一二月，正是百货辐辏，销运兴旺之时，即在生丝一业，大宗输出，为贸易最好景况也。果于上半年，生丝商况不振，七八月以后，逐步发动，十一二月，时价涨至千弗以上，悉为外商所买，国内机织场，反为之休业焉。</p>',107)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
